// The static exercise bank (engine-verified, generated by scripts/gen-puzzles.ts)
// plus the curated theory endgames, as exercises.
import bankJson from '../data/puzzles.json';
import { THEORY_ENDGAMES, ENDGAME_STUDIES } from '../data/endgames';
import type { Exercise } from './types';

const theory: Exercise[] = THEORY_ENDGAMES.map((t) => ({
  id: `theory-${t.id}`, source: 'theory', kind: 'endgame', theme: t.theme, fen: t.fen, solution: [], rating: t.rating,
  phase: 'endgame', prompt: t.idea, explanation: t.steps.join(' '), goal: t.goal, title: t.title,
}));
const studies: Exercise[] = ENDGAME_STUDIES.map((t) => ({
  id: `study-${t.id}`, source: 'theory', kind: 'tactic', theme: 'eg_tactic', fen: t.fen, solution: t.solution, rating: t.rating,
  phase: 'endgame', prompt: t.prompt, explanation: t.idea, goal: 'best', title: t.title,
}));
export const BANK: Exercise[] = [...(bankJson as Exercise[]), ...theory, ...studies];
/** Tactics that happen in endgames: the studies plus engine-found endgame puzzles. */
export const isEndgameTactic = (e: Exercise) => e.theme === 'eg_tactic' || (e.kind === 'tactic' && e.phase === 'endgame');
export const BANK_BY_ID = new Map(BANK.map((e) => [e.id, e]));
